>'opening_total_qty','مبلغ کل ابتدای دوره'=>'opening_total_amount','مبلغ تخفیف ابتدای دوره'=>'opening_discount_amount','مبلغ مالیات ابتدای دوره'=>'opening_tax_amount','مبلغ عوارض ابتدای دوره'=>'opening_duty_amount','مبلغ قابل پرداخت ابتدای دوره'=>'opening_payable_amount','تعداد کارتن وارده'=>'inbound_carton_qty','تعداد جز وارده'=>'inbound_part_qty','تعداد کل وارده'=>'inbound_total_qty','مبلغ کل وارده'=>'inbound_total_amount','مبلغ تخفیف وارده'=>'inbound_discount_amount','مبلغ مالیات وارده'=>'inbound_tax_amount','مبلغ عوارض وارده'=>'inbound_duty_amount','مبلغ قابل پرداخت وارده'=>'inbound_payable_amount','تعداد کارتن صادره'=>'outbound_carton_qty','تعداد جز صادره'=>'outbound_part_qty','تعداد کل صادره'=>'outbound_total_qty','مبلغ کل صادره'=>'outbound_total_amount','pricee'=>'pricee','مبلغ تخفیف صادره'=>'outbound_discount_amount','مبلغ مالیات صارده'=>'outbound_tax_amount','مبلغ عوارض صادره'=>'outbound_duty_amount','مبلغ قابل پرداخت صادره'=>'outbound_payable_amount','موجودی دوره کارتن'=>'current_period_carton_qty','موجودی دوره جز'=>'current_period_part_qty','موجودی دوره کل'=>'current_period_total_qty','تعداد در کارتن'=>'carton_size','آخرین قیمت تمام شده'=>'last_cost_price','آخرین قیمت خرید'=>'last_purchase_price','ارزش ریالی بر اساس آخرین قیمت تمام شده'=>'stock_value_by_last_cost','ارزش ریالی بر اساس قیمت فروش 1'=>'stock_value_by_sale_price_1','قیمت فروش خرده'=>'retail_price','قیمت فروش عمده'=>'wholesale_price','پورسانت خورده'=>'retail_commission','پورسانت خرده'=>'retail_commission','پورسانت عمده'=>'wholesale_commission','وزن موجود'=>'current_weight','حجم موجود'=>'current_volume','کد گروه درختی'=>'product_tree_group_code','نام گروه درختی'=>'product_tree_group_name','بارکد'=>'barcode','کد کنترلی'=>'control_code','کد گروه'=>'group_code','نام گروه'=>'group_name','مدت وصول خرده'=>'retail_collection_days','sudozian'=>'sudozian','موجودی فعلی مبنا'=>'current_base_stock','موجودی فعلی جز'=>'current_part_stock','موجودی فعلی کل'=>'current_total_stock','برند'=>'brand_name','تاریخ آخر