    public static function readUploadedFile(array $file,string $mode,int $actor):array
    {
        if(!in_array($mode,self::MODES,true))$mode='skip_duplicates';$stored=SpreadsheetImportReader::store($file,'inventory-imports');$batch=0;try{$book=SpreadsheetImportReader::read($stored['path'],$stored['extension']);$c=self::detectWorkbookSource($book);if(!$c)throw new InvalidArgumentException('جدول، شیت یا سرستون‌های معتبر موجودی پیدا نشد.');$selected=count($c)===1?$c[0]:null;$meta=['stored_name'=>$stored['stored_name'],'extension'=>$stored['extension'],'mime'=>$stored['mime'],'candidates'=>array_map([self::class,'candidateMeta'],$c)];$batch=InventoryRepository::createBatch(['source_type'=>$stored['source_type'],'file_name'=>$stored['file_name'],'file_hash'=>$stored['file_hash'],'detected_sheet'=>$selected['sheet_name']??null,'detected_table'=>$selected['table_name']??null,'import_mode'=>$mode,'status'=>$selected?'uploaded':'awaiting_source_selection','started_by'=>$actor,'metadata_json'=>json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);if($selected)return['batch_id'=>$batch,'needs_selection'=>false,'summary'=>self::storeToStaging($batch,$selected)];return['batch_id'=>$batch,'needs_selection'=>true,'candidates'=>$meta['candidates']];}catch(Throwable $e){@unlink($stored['path']);if($batch)try{InventoryRepository::finish($batch,'failed',0,0,0,'پردازش فایل انجام نشد.');}catch(Throwable $ignored){}throw$e;}
    }
    public static function detectWorkbookSource(array $book):array{$tables=$sheets=$headers=[];foreach($book['sheets']??[]as$s){if(!($s['visible']??true))continue;foreach($s['tables']??[]as$t)if(SalesDataNormalizer::normalizeHeader($t['name']??'')==='tblanbar')$tables[]=self::candidate($s,SpreadsheetImportReader::crop($s['rows'],(string)($t['ref']??'')),'table',(string)$t['name'],(string)($t['ref']??''));if(SalesDataNormalizer::normalizeHeader($s['name']??'')==='tblanbar')$sheets[]=self::candidate($s,$s['rows']??[],'sheet');if(self::hasRequired($s['rows'][0]??[]))$headers[]=self::candidate($s,$s['rows']??[],'headers');}return$tables?:($sheets?:$headers);}
    public static function mapColumns(array $headers,?array $maps=null):array{$maps=$maps??InventoryRepository::mappings();$by=[];foreach($maps as$m)$by[SalesDataNormalizer::normalizeHeader($m['source_header'])]=$m;$cols=[];foreach($headers as$i=>$h){$n=SalesDataNormalizer::normalizeHeader($h);if(isset($by[$n]))$cols[$i]=$by[$n];}$keys=array_column($cols,'normalized_key');$missing=[];foreach(self::REQUIRED as$label=>$key)if(!in_array($key,$keys,true))$missing[]=$label;if(!in_array('current_period_total_qty',$keys,true)&&!in_array('current_total_stock',$keys,true))$missing[]='موجودی دوره کل یا موجودی فعلی کل';return['columns'=>$cols,'missing_required'=>$missing];}
    public static function validateRow(array $n,array $raw=[]):array{$e=[];foreach(['کد کالا'=>'product_code','نام کالا'=>'product_name']as$label=>$key)if(trim((string)($n[$key]??''))==='')$e[]=['code'=>'required_field','message'=>"فیلد «{$label}» الزامی است."];foreach(self::mappingDefinitions()as$m)if($m['data_type']==='decimal'){foreach($raw as$h=>$v)if(SalesDataNormalizer::normalizeHeader($h)===SalesDataNormalizer::normalizeHeader($m['source_header'])&&trim((string)$v)!==''&&($n[$m['normalized_key']]??null)===null)$e[]=['code'=>'invalid_number','message'=>'مقدار «'.$m['source_header'].'» عدد معتبر نیست.'];}return$e;}
    public static function buildSourceUniqueKey(array $n):string{return sha1(implode('|',array_map(static fn($k)=>trim((string)($n[$k]??'')),['product_code','index_code','expire_date_raw','manufacturer_code','brand_name'])));}
    public static function storeToStaging(int $batch,array $c):array{$rows=$c['rows']??[];if(!$rows)throw new InvalidArgumentException('منبع انتخاب‌شده فاقد داده است.');$heads=array_map(static fn($v)=>trim((string)$v),array_shift($rows));$map=self::mapColumns($heads);if($map['missing_required'])throw new InvalidArgumentException('سرستون‌های الزامی یافت نشد: '.implode('، ',$map['missing_required']));$b=Database::fetch('SELECT import_mode,metadata_json FROM sales_import_batches WHERE id=? AND source_module="inventory_aggregate"',[$batch]);$seen=[];$s=['total_rows'=>0,'valid_rows'=>0,'invalid_rows'=>0,'duplicate_rows'=>0,'ready_rows'=>0];foreach($rows as$i=>$vals){if(!array_filter($vals,static fn($v)=>trim((string)$v)!==''))continue;$raw=[];foreach($heads as$j=>$h)if($h!=='')$raw[$h]=(string)($vals[$j]??'');$n=[];foreach($map['columns']as$j=>$m){$v=$vals[$j]??'';$n[$m['normalized_key']]=$m['data_type']==='decimal'?SalesDataNormalizer::normalizeDecimal($v):SalesDataNormalizer::normalizePersianArabicDigits($v);}$n['expire_date_raw']=SalesDataNormalizer::normalizePersianArabicDigits($n['expire_date_raw']??'');$n['expire_date']=SalesDataNormalizer::normalizeDate($n['expire_date_raw']);$n['last_purchase_date_raw']=SalesDataNormalizer::normalizePersianArabicDigits($n['last_purchase_date_raw']??'');$n['last_purchase_date']=SalesDataNormalizer::normalizeDate($n['last_purchase_date_raw']);$key=self::buildSourceUniqueKey($n);$dup=isset($seen[$key])||InventoryRepository::existing($key)!==null;$seen[$key]=true;$n['_duplicate']=$dup;$errors=self::validateRow($n,$raw);if($dup&&$b['import_mode']==='fail_on_duplicate')$errors[]=['code'=>'duplicate','message'=>'این ردیف موجودی تکراری است.'];$status=$errors?'invalid':(($dup&&$b['import_mode']==='skip_duplicates')?'duplicate':'valid');InventoryRepository::stage($batch,$i+2,$raw,$n,$status,$errors,$key);$s['total_rows']++;if($dup)$s['duplicate_rows']++;if($status==='invalid')$s['invalid_rows']++;else$s['valid_rows']++;if($status==='valid')$s['ready_rows']++;} $meta=json_decode((string)$b['metadata_json'],true)?:[];$meta['selected_candidate']=self::candidateMeta($c);InventoryRepository::updateDetection($batch,$c,'preview',$meta);InventoryRepository::counts($batch,$s);return$s;}
    public static function summary(int $batch):array{$b=Database::fetch('SELECT * FROM sales_import_batches WHERE id=? AND source_module="inventory_aggregate"',[$batch]);if(!$b)throw new InvalidArgumentException('Batch پیدا نشد.');return['total_rows'=>(int)$b['total_rows'],'valid_rows'=>(int)$b['valid_rows'],'invalid_rows'=>(int)$b['invalid_rows'],'duplicate_rows'=>(int)$b['duplicate_rows'],'ready_rows'=>max(0,(int)$b['valid_rows']-($b['import_mode']==='skip_duplicates'?(int)$b['duplicate_rows']:0))];}
    public static function selectCandidate(int $id,string $key,int $actor,bool $admin=false):array{$b=InventoryRepository::batchForActor($id,$actor,$admin);if(!$b||$b['status']!=='awaiting_source_selection')throw new InvalidArgumentException('Batch قابل انتخاب منبع نیست.');$m=json_decode((string)$b['metadata_json'],true)?:[];$book=SpreadsheetImportReader::read(SpreadsheetImportReader::resolveStored('inventory-imports',(string)($m['stored_name']??'')),(string)($m['extension']??''));foreach(self::detectWorkbookSource($book)as$c)if(hash_equals($c['key'],$key))return self::storeToStaging($id,$c);throw new InvalidArgumentException('منبع انتخاب‌شده معتبر نیست.');}
    public static function commitValidRows(int $id,int $actor,bool $admin=false):array{$pdo=Database::connection();$pdo->beginTransaction();try{$b=InventoryRepository::batchForActor($id,$actor,$admin,true);if(!$b||$b['status']!=='preview')throw new InvalidArgumentException('Batch آماده تایید نهایی نیست.');if($b['import_mode']==='fail_on_duplicate'&&(int)$b['duplicate_rows']>0)throw new DomainException('داده تکراری یافت شد؛ ورود نهایی لغو شد.');$rows=InventoryRepository::rows($id,'valid');if(!$rows&&(int)$b['total_rows']>0&&!($b['import_mode']==='skip_duplicates'&&(int)$b['duplicate_rows']>0))throw new DomainException('هیچ ردیف معتبری برای ورود نهایی وجود ندارد.');$inserted=$updated=$skipped=0;if($b['import_mode']==='skip_duplicates')foreach(InventoryRepository::rows($id,'duplicate')as$r){InventoryRepository::mark((int)$r['id'],'skipped');$skipped++;}foreach($rows as$r){$n=json_decode((string)$r['normalized_json'],true)?:[];$raw=json_decode((string)$r['raw_json'],true)?:[];$existing=InventoryRepository::existing((string)$r['source_unique_key'],true);if($existing&&$b['import_mode']==='skip_duplicates'){InventoryRepository::mark((int)$r['id'],'skipped');$skipped++;continue;}InventoryRepository::save($id,(string)$b['source_type'],(string)$r['source_unique_key'],$n,$raw,$existing?(int)$existing['id']:null);InventoryRepository::mark((int)$r['id'],'committed');$existing?$updated++:$inserted++;}InventoryRepository::finish($id,'completed',$inserted,$updated,$skipped);$pdo->commit();return compact('inserted','updated','skipped');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Inventory commit: '.$e->getMessage());if($e instanceof InvalidArgumentException||$e instanceof DomainException)throw$e;throw new RuntimeException('ورود نهایی موجودی انجام نشد.');}}
    public static function rollbackBatch(int $id,int $actor,bool $admin=false):void{$pdo=Database::connection();$pdo->beginTransaction();try{$b=InventoryRepository::batchForActor($id,$actor,$admin,true);if(!$b||in_array($b['status'],['completed','cancelled'],true))throw new InvalidArgumentException('Batch قابل لغو نیست.');Database::execute('UPDATE staging_sales_data SET validation_status="cancelled" WHERE import_batch_id=? AND source_module="inventory_aggregate"',[$id]);InventoryRepository::finish($id,'cancelled');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
    private static function hasRequired(array $h):bool{$n=SalesDataNormalizer::normalizeHeaders($h);foreach(array_keys(self::REQUIRED)as$r)if(!in_array(SalesDataNormalizer::normalizeHeader($r),$n,true))return false;return in_array(SalesDataNormalizer::normalizeHeader('موجودی دوره کل'),$n,true)||in_array(SalesDataNormalizer::normalizeHeader('موجودی فعلی کل'),$n,true);}
    private static function candidate(array $s,array $rows,string $d,string $table='',string $ref=''):array{return['key'=>hash('sha256',$d.'|'.($s['name']??'').'|'.$table.'|'.$ref),'sheet_name'=>(string)($s['name']??''),'table_name'=>$table?:null,'detection'=>$d,'ref'=>$ref?:null,'headers'=>$rows[0]??[],'rows'=>$rows];}
    private static function candidateMeta(array $c):array{return['key'=>$c['key'],'sheet_name'=>$c['sheet_name'],'table_name'=>$c['table_name'],'detection'=>$c['detection'],'ref'=>$c['ref'],'headers'=>$c['headers']];}
}
